<?php require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/functions.php'; require_admin(); $users=db()->query('SELECT id,name,email,role,created_at FROM users ORDER BY created_at DESC')->fetchAll(); ?>
